import * as s from '@exodus/crypto/secp256k1'

/* Compatibility layer with tiny-secp256k1 v2 / bitcoinerlab-secp256k1 */
/* Only intended to be used from @exodus/bitcoinjs, though provides full API */

const INVALID_TWEAK_MESSAGE = 'Invalid tweak result' // must match ./secp256k1
const defaultCompressedValue = (publicKey) => publicKey?.length === 33 // value only needed when publicKey is valid

// This is what ecpair expects from tweak API, and then rechecks the result and re-throws
// We do this only for the tweaks API
const throwTweakToNull = (f) => {
  try {
    return f()
  } catch (e) {
    if (e.message === 'Expected valid private scalar: 0 < scalar < curve.n') return null // publicKeyTweakMultiply can throw that
    if (e.message === INVALID_TWEAK_MESSAGE) return null
    throw e
  }
}

// We throw on invalid type and validate content
// tiny-secp256k1 returns false on invalid type
const throwIsValidToFalse = (f) => {
  try {
    return Boolean(f())
  } catch {
    return false
  }
}

// Exports

export const isPoint = (publicKey) => throwIsValidToFalse(() => s.publicKeyIsValid({ publicKey })) // 33 or 65

export const isPointCompressed = (publicKey) =>
  throwIsValidToFalse(() => s.publicKeyIsValid({ publicKey, compressed: true })) // 33

export const isPrivate = (privateKey) =>
  throwIsValidToFalse(() => s.privateKeyIsValid({ privateKey }))

export const isXOnlyPoint = (xOnly) => throwIsValidToFalse(() => s.xOnlyIsValid({ xOnly }))

export const pointFromScalar = (privateKey, compressed = true) =>
  s.privateKeyToPublicKey({ privateKey, compressed })

export const pointCompress = (publicKey, compressed = defaultCompressedValue(publicKey)) =>
  s.publicKeyConvert({ publicKey, compressed }) // this, despite its name, does not compress if second option is not specified

export const pointAdd = (publicKey, tweakPoint, compressed) =>
  throwTweakToNull(() => s.publicKeyTweakAddPoint({ publicKey, tweakPoint, compressed }))

export const pointAddScalar = (publicKey, tweak, compressed) =>
  throwTweakToNull(() => s.publicKeyTweakAddScalar({ publicKey, tweak, compressed }))

export const pointMultiply = (publicKey, tweak, compressed) =>
  throwTweakToNull(() => s.publicKeyTweakMultiply({ publicKey, tweak, compressed }))

export const privateAdd = (privateKey, tweak) =>
  throwTweakToNull(() => s.privateKeyTweakAdd({ privateKey, tweak }))

export const privateSub = (privateKey, tweak) =>
  throwTweakToNull(() => s.privateKeyTweakSubtract({ privateKey, tweak }))

export const privateNegate = (privateKey) =>
  throwTweakToNull(() => s.privateKeyTweakNegate({ privateKey }))

export const xOnlyPointAddTweak = (xOnly, tweak) =>
  throwTweakToNull(() => {
    const publicKey = s.xOnlyTweakAdd({ xOnly, tweak })
    return { parity: publicKey[0] % 2, xOnlyPubkey: publicKey.subarray(1) }
  })

export const signRecoverable = (hash, privateKey, extraEntropy = null) => {
  const result = s.ecdsaSignHashSync({ hash, privateKey, extraEntropy, recovery: true })
  return { signature: result.signature, recoveryId: result.recovery }
}

export const sign = (hash, privateKey, extraEntropy = null) =>
  s.ecdsaSignHashSync({ hash, privateKey, extraEntropy })

export const verify = (hash, publicKey, signature) =>
  s.ecdsaVerifyHashSync({ hash, publicKey, signature }) // unlike tiny-secp256k1, we are always strict. this will cause false negatives but prevent malleability

export const signSchnorr = (data, privateKey, extraEntropy) =>
  s.schnorrSignSync({ data, privateKey, extraEntropy })

export const verifySchnorr = (data, xOnly, signature) =>
  s.schnorrVerifySync({ data, xOnly, signature })

export const xOnlyPointFromPoint = (publicKey) => s.publicKeyToX({ publicKey })

export const xOnlyPointFromScalar = (privateKey) =>
  s.publicKeyToX({ publicKey: s.privateKeyToPublicKey({ privateKey, compressed: true }) })
